from scipy.stats import norm
import numpy as np

def d1_d2(S, K, T, r, sigma):
    d1 = (np.log(S / K) + (r + 0.5 * sigma ** 2) * T) / (sigma * np.sqrt(T))
    return d1, d1 - sigma * np.sqrt(T)

def vega(S, K, T, r, sigma):
    d1, _ = d1_d2(S, K, T, r, sigma)
    return S * norm.pdf(d1) * np.sqrt(T)

def vanna_analytic(S, K, T, r, sigma):
    d1, d2 = d1_d2(S, K, T, r, sigma)
    return -norm.pdf(d1) * d2 / sigma

def volga_analytic(S, K, T, r, sigma):
    d1, d2 = d1_d2(S, K, T, r, sigma)
    return vega(S, K, T, r, sigma) * d1 * d2 / sigma

def bs_call(S, K, T, r, sigma):
    d1, d2 = d1_d2(S, K, T, r, sigma)
    return S * norm.cdf(d1) - K * np.exp(-r * T) * norm.cdf(d2)

# Finite-difference check: bump sigma by 0.0001 and re-difference the call price
S, K, T, r, sigma = 26500, 25700, 30 / 365, 0.065, 0.168
h = 1e-4

delta_up = (bs_call(S, K, T, r, sigma + h) - bs_call(S, K, T, r, sigma - h)) / (2 * h)  # cross check vs vega
vanna_fd = (vega(S, K, T, r, sigma + h) - vega(S, K, T, r, sigma - h)) / (2 * h)
volga_fd = (vega(S, K, T, r, sigma + h) - 2 * vega(S, K, T, r, sigma) + vega(S, K, T, r, sigma - h)) / h ** 2

print(f"Vanna: analytic {vanna_analytic(S, K, T, r, sigma):.4f}, finite-diff {vanna_fd:.4f}")
print(f"Volga: analytic {volga_analytic(S, K, T, r, sigma):.4f}, finite-diff {volga_fd:.4f}")
